// Step 1: Parse Query Filters
const input = $input.first().json;

const userId = input.user_id;
const filters = input.filters || input;
const status = filters.status || null;
const priority = filters.priority || null;
const dateFrom = filters.date_from || null;
const dateTo = filters.date_to || null;
const limit = filters.limit || 20;

return [{
  json: {
    ...input,
    user_id: userId,
    filter_status: status,
    filter_priority: priority,
    filter_date_from: dateFrom,
    filter_date_to: dateTo,
    filter_limit: limit
  }
}];

const req = $('Parse Query Filters').first().json;
const rows = $input.all().map(item => item.json);

let responseText = '';
if (!rows || rows.length === 0) {
  responseText = 'No encontré tareas pendientes con esos criterios.';
} else {
  const taskLines = rows.map((t, idx) => {
    const dateStr = t.due_date ? ` (Vence: ${t.due_date}${t.time_known && t.due_time ? ' ' + t.due_time : ''})` : '';
    const prioStr = t.priority && t.priority !== 'normal' ? ` [${t.priority}]` : '';
    return `${idx + 1}. ${t.title}${prioStr}${dateStr}`;
  });
  responseText = `📋 Tus tareas:\n` + taskLines.join('\n');
}

return [{
  json: {
    ok: true,
    status: 'completed',
    correlation_id: req.correlation_id,
    data: {
      tasks: rows,
      count: rows.length,
      formatted_response: responseText
    }
  }
}];
